#!/usr/bin/env python3
# P-B18《尾部承载假说》· 双胞胎测试卡 × 谱带消融 (单 kernel 自训自测)
# 判据先冻: PREREG_PB18_tail_resolution.md | 卡与语料 b64 内嵌 + sha 自校
import os, json, time, base64, hashlib
import numpy as np, torch
os.system("python -m pip uninstall -y -q torchao 2>/dev")
from transformers import AutoTokenizer, AutoModelForCausalLM
from peft import LoraConfig, get_peft_model, TaskType

MOUNT = "/kaggle/input/models/qwen-lm/qwen2.5/transformers/0.5b-instruct/1"
dev = "cuda"
OUT = "/kaggle/working"
SPRING = base64.b64decode("").decode()
assert hashlib.sha256(SPRING.encode()).hexdigest() == "d38e57905b30a43ac624fd07b4a50b7704a6b712236635eefe6f3a8779394262", "corpus drift"
CARD_RAW = base64.b64decode("")
assert hashlib.sha256(CARD_RAW).hexdigest() == "512f9869d5d1602689c3ab8c1933505065c38bb591fc3d796c3a875cb7567df5", "card drift"
CARD = json.loads(CARD_RAW.decode())
RECIPE = dict(r=16, lora_alpha=32, lora_dropout=0.05, target_modules=["q_proj","k_proj","v_proj","o_proj","gate_proj","up_proj","down_proj"])
HP = dict(lr=1e-4, batch=2, accum=4, seed=13, epochs=6)
torch.manual_seed(HP["seed"]); np.random.seed(HP["seed"])

tok = AutoTokenizer.from_pretrained(MOUNT)
model = AutoModelForCausalLM.from_pretrained(MOUNT, dtype=torch.float16)
model = get_peft_model(model, LoraConfig(task_type=TaskType.CAUSAL_LM, bias="none", **RECIPE))
model.to(dev); model.train()

def enc_pair(u, a):
    msgs = [{"role": "user", "content": u}, {"role": "assistant", "content": a}]
    pre = tok.apply_chat_template(msgs[:1] + [{"role": "assistant", "content": ""}], tokenize=False, add_generation_prompt=True)
    full = tok.apply_chat_template(msgs, tokenize=False, add_generation_prompt=False)
    fi = tok(full, add_special_tokens=False)["input_ids"]; pi = tok(pre, add_special_tokens=False)["input_ids"]
    return fi, [-100] * len(pi) + fi[len(pi):]

pairs = []
for line in SPRING.splitlines():
    if not line.strip(): continue
    o = json.loads(line); pairs.append(enc_pair(o["user"], o["assistant"]))
opt = torch.optim.AdamW([p for p in model.parameters() if p.requires_grad], lr=HP["lr"])
t0 = time.time()
for ep in range(1, HP["epochs"] + 1):
    perm = np.random.permutation(len(pairs)); tot = 0.0
    for si, idx in enumerate(perm):
        fi, la = pairs[int(idx)]
        ids = torch.tensor([fi]).to(dev); lab = torch.tensor([la]).to(dev); at = torch.ones_like(ids)
        loss = model(input_ids=ids, attention_mask=at, labels=lab).loss / HP["accum"]
        loss.backward(); tot += float(loss) * HP["accum"]
        if (si + 1) % HP["accum"] == 0 or si == len(perm) - 1: opt.step(); opt.zero_grad()
    print(f"ep{ep} loss {tot/len(perm):.3f} {time.time()-t0:.0f}s", flush=True)

# --- 挂载断言 (PB10 铁律) ---
named = {n: p for n, p in model.named_parameters() if "lora_" in n}
assert len(named) > 0, "无 lora 参数"
assert all(float(p.detach().abs().sum()) > 0 for n, p in named.items() if ".lora_B." in n), "lora_B 全零 —— 未挂载"

def nll_plain(text):
    e = tok(text, add_special_tokens=False, return_tensors="pt").to(dev)
    with torch.no_grad(): l = model(**e, labels=e["input_ids"]).loss
    return float(l)

# --- SELFTRAIN 内检 ---
trained_sent = json.loads(SPRING.splitlines()[0])["assistant"]
with model.disable_adapter():
    e = tok(trained_sent, add_special_tokens=False, return_tensors="pt").to(dev)
    with torch.no_grad(): n_base = float(model(**e, labels=e["input_ids"]).loss)
n_full = nll_plain(trained_sent)
assert n_full < n_base, f"SELFTRAIN 内检失败 full={n_full:.4f} base={n_base:.4f} —— 整轮作废"

# --- 谱带消融: 每模块 ΔW=B@A 截 r 项 SVD, 剔向重分解; k=头臂剔能一半之方向数, 三臂同计数 ---
R = RECIPE["r"]
ORIG = {n: p.detach().cpu().clone() for n, p in named.items()}  # 臂前必回卷, 防叠刀
def band_masks(s, mode, rng):
    e = s ** 2; E = float(e.sum())
    k = int(np.searchsorted(np.cumsum(np.sort(e)[::-1]), 0.5 * E) + 1)
    keep = np.ones(len(s), bool)
    if mode == "head": keep[np.argsort(s)[::-1][:k]] = False
    elif mode == "tail": keep[np.argsort(s)[:k]] = False
    else: keep[rng.choice(len(s), k, replace=False)] = False
    return keep, k, float(e[~keep].sum() / E)

def apply_state(mode, seed=7):
    with torch.no_grad():
        for n, p in named.items(): p.copy_(ORIG[n].to(p.device))
    rng = np.random.default_rng(seed); stats = []
    groups = {}
    for n, p in named.items():
        groups.setdefault(n.split(".lora_")[0], {})[n.split(".lora_")[1][0]] = p
    for base, d in groups.items():
        pB, pA = d["B"], d["A"]
        B = pB.detach().cpu().float().numpy(); A = pA.detach().cpu().float().numpy()
        U, s, Vt = np.linalg.svd(B @ A, full_matrices=False)
        U, s, Vt = U[:, :R], s[:R], Vt[:R, :]
        keep, k, lost = band_masks(s, mode, rng)
        root = np.sqrt(np.maximum(s, 0) * keep)
        Bn = torch.tensor(U * root[None, :], dtype=pB.dtype, device=pB.device)
        An = torch.tensor(Vt * root[:, None], dtype=pA.dtype, device=pA.device)
        with torch.no_grad(): pB.copy_(Bn); pA.copy_(An)
        stats.append(dict(base=base.split("layers.")[-1][:24], k=int(k), energy_lost=round(lost, 3)))
    return stats

def card_read():
    res = {}
    for lev, ps in CARD["levels"].items():
        ds = [nll_plain(a) - nll_plain(b) for a, b in ps]
        row = dict(mean_abs=round(float(np.mean(np.abs(ds))), 4), deltas=[round(d, 4) for d in ds])
        if lev.startswith("L1"): row["acc_a_lower"] = round(float(np.mean([d < 0 for d in ds])), 3)
        res[lev] = row
    return res

REPORT = dict(case="P-B18", card_sha="512f9869d5d1602689c3ab8c1933505065c38bb591fc3d796c3a875cb7567df5"[:16], spring_sha="d38e57905b30a43ac624fd07b4a50b7704a6b712236635eefe6f3a8779394262"[:16],
              selftrain=dict(base=round(n_base, 4), full=round(n_full, 4)), states={})
def flush(tag):
    REPORT["_meta"] = dict(stage=tag, t=round(time.time() - t0, 1), _selfcheck="pb18_ok" if tag == "final" else None)
    json.dump(REPORT, open(f"{OUT}/report_pb18.json", "w"), ensure_ascii=False)
    print("REPORT_LINE::" + base64.b64encode(json.dumps(REPORT, ensure_ascii=False).encode()).decode()[:4000], flush=True)

REPORT["states"]["full"] = card_read(); flush("full")
for mode in ("head", "tail", "random"):
    REPORT["ablation_stats_" + mode] = apply_state(mode)
    REPORT["states"]["ablate_" + mode] = card_read()
    flush("ablate_" + mode)
flush("final")
print("DONE PB18", flush=True)
